package uk.co.afileonmotorsport.pitlane;

import android.util.Base64;

import java.io.ByteArrayInputStream;
import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.util.zip.GZIPInputStream;

/** Exact Pitlane Pro v0.7.0 web module, gzip-packed only to keep the Android source compact. */
final class PitlaneProBundle {
    private static final String DATA = "";

    private PitlaneProBundle() {}

    static String script() {
        try {
            byte[] packed = Base64.decode(DATA, Base64.DEFAULT);
            try (GZIPInputStream in = new GZIPInputStream(new ByteArrayInputStream(packed));
                 ByteArrayOutputStream out = new ByteArrayOutputStream(40000)) {
                byte[] buf = new byte[4096];
                int n;
                while ((n = in.read(buf)) != -1) out.write(buf, 0, n);
                return out.toString(StandardCharsets.UTF_8.name());
            }
        } catch (IOException e) {
            throw new IllegalStateException("Pitlane Pro bundle could not be loaded", e);
        }
    }
}
